INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('afonso', 'Afonso', 'indefinido', 'Oi, eu sou o Afonso. Vim para o abrigo depois que minha tutora faleceu. Sou quietinho e bonzinho.', 'uma casinha nova, porque a minha está muito desgastada', 'Oi, eu sou o Afonso. Vim para o abrigo depois que minha tutora faleceu. Sou quietinho e bonzinho. Papai Noel, neste Natal eu queria muito ganhar uma casinha nova, porque a minha está muito desgastada.', '/pets/afonso.png', 'cama', '[]', 1, 'disponivel', 0);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('afonso-2', 'Afonso', 'cachorro', 'Oi, eu sou o Afonso. Cheguei ao abrigo este ano, depois de ser abandonado perto do aeroporto. Por sorte, encontrei pessoas que cuidaram de mim.', 'um kit de brinquedos para dividir com meus amigos de baia', 'Oi, eu sou o Afonso. Cheguei ao abrigo este ano, depois de ser abandonado perto do aeroporto. Por sorte, encontrei pessoas que cuidaram de mim. Papai Noel, neste Natal eu queria muito ganhar um kit de brinquedos para dividir com meus amigos de baia.', '/pets/afonso-2.png', 'brinquedo', '[]', 1, 'disponivel', 1);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('aipim', 'Aipim', 'cachorro', 'Oi, eu sou o Aipim. Apareci na porta do abrigo numa noite de chuva, em 2023, com a patinha machucada. Fui tratado e amado, mas nunca escolhido.', 'uma caminha nova para colocar dentro do meu pneu', 'Oi, eu sou o Aipim. Apareci na porta do abrigo numa noite de chuva, em 2023, com a patinha machucada. Fui tratado e amado, mas nunca escolhido. Papai Noel, neste Natal eu queria muito ganhar uma caminha nova para colocar dentro do meu pneu.', '/pets/aipim.png', 'cama', '[]', 1, 'disponivel', 2);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('alonso', 'Alonso', 'cachorro', 'Oi, eu sou o Alonso. Fui encontrado comendo carcaças na beira da BR e com parvovirose. Fiquei muito mal, mas sobrevivi.', 'um brinquedo', 'Oi, eu sou o Alonso. Fui encontrado comendo carcaças na beira da BR e com parvovirose. Fiquei muito mal, mas sobrevivi. Papai Noel, neste Natal eu queria muito ganhar um brinquedo.', '/pets/alonso.png', 'brinquedo', '[]', 1, 'disponivel', 3);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('anna', 'Anna', 'gato', 'Oi, eu sou a Anna. Cheguei ao abrigo bem pequenininha e hoje tenho uns 5 anos. Cresci no gatil e ainda sonho com uma família.', 'uma casinha pequena com almofadinha para descansar quentinha', 'Oi, eu sou a Anna. Cheguei ao abrigo bem pequenininha e hoje tenho uns 5 anos. Cresci no gatil e ainda sonho com uma família. Papai Noel, neste Natal eu queria muito ganhar uma casinha pequena com almofadinha para descansar quentinha.', '/pets/anna.png', 'cama', '[]', 1, 'disponivel', 4);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('apolo', 'Apolo', 'cachorro', 'Oi, eu sou o Apolo. Estou no abrigo desde filhote, em 2020. Divido a baia com a Lasanha e nós amamos água: vivemos derrubando as bacias!', 'um tapete chafariz de água para cães', 'Oi, eu sou o Apolo. Estou no abrigo desde filhote, em 2020. Divido a baia com a Lasanha e nós amamos água: vivemos derrubando as bacias! Papai Noel, neste Natal eu queria muito ganhar um tapete chafariz de água para cães.', '/pets/apolo.png', 'conforto', '[]', 1, 'disponivel', 5);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('ariel', 'Ariel', 'indefinido', 'Oi, eu sou a Ariel. Fui resgatada das ruas muito magrinha e debilitada. Hoje tenho comida, proteção e muito carinho no abrigo.', 'um kit de sachês bem gostosos', 'Oi, eu sou a Ariel. Fui resgatada das ruas muito magrinha e debilitada. Hoje tenho comida, proteção e muito carinho no abrigo. Papai Noel, neste Natal eu queria muito ganhar um kit de sachês bem gostosos.', '/pets/ariel.png', 'petisco', '[]', 1, 'disponivel', 6);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('bartira', 'Bartira', 'indefinido', 'Oi, eu sou a Bartira. Vivia em uma construção e corria risco por lá. Ainda sou muito na minha, mas amo a minha casinha.', 'uma almofadinha ou um cobertor bem quentinho', 'Oi, eu sou a Bartira. Vivia em uma construção e corria risco por lá. Ainda sou muito na minha, mas amo a minha casinha. Papai Noel, neste Natal eu queria muito ganhar uma almofadinha ou um cobertor bem quentinho.', '/pets/bartira.png', 'cama', '[]', 1, 'disponivel', 7);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('bebel', 'Bebel', 'indefinido', 'Oi, eu sou a Bebel. Tenho uns 5 anos e conheci de perto as dificuldades das ruas. Hoje estou protegida no abrigo.', 'uma casinha pequena e confortável para dormir em paz', 'Oi, eu sou a Bebel. Tenho uns 5 anos e conheci de perto as dificuldades das ruas. Hoje estou protegida no abrigo. Papai Noel, neste Natal eu queria muito ganhar uma casinha pequena e confortável para dormir em paz.', '/pets/bebel.png', 'cama', '[]', 1, 'disponivel', 8);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('becky', 'Becky', 'indefinido', 'Oi, eu sou a Becky. Fui encontrada no sol com meus irmãos, todos passando mal. Hoje amo brincar.', 'um brinquedinho', 'Oi, eu sou a Becky. Fui encontrada no sol com meus irmãos, todos passando mal. Hoje amo brincar. Papai Noel, neste Natal eu queria muito ganhar um brinquedinho.', '/pets/becky.png', 'outros', '[]', 1, 'disponivel', 9);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('belinda', 'Belinda', 'cachorro', 'Oi, eu sou a Belinda, uma das moradoras mais antigas daqui. Cheguei grávida de 7 bebês. Todos foram adotados, menos eu.', 'uma caminha suspensa ou de pneu, para não sujar de terra', 'Oi, eu sou a Belinda, uma das moradoras mais antigas daqui. Cheguei grávida de 7 bebês. Todos foram adotados, menos eu. Papai Noel, neste Natal eu queria muito ganhar uma caminha suspensa ou de pneu, para não sujar de terra.', '/pets/belinda.png', 'cama', '[]', 1, 'disponivel', 10);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('bertha', 'Bertha', 'cachorro', 'Oi, eu sou a Bertha. Passei muito tempo amarrada embaixo de uma árvore, sem proteção. Amo carinho e atenção.', 'algumas guloseimas bem gostosas', 'Oi, eu sou a Bertha. Passei muito tempo amarrada embaixo de uma árvore, sem proteção. Amo carinho e atenção. Papai Noel, neste Natal eu queria muito ganhar algumas guloseimas bem gostosas.', '/pets/bertha.png', 'petisco', '[]', 1, 'disponivel', 11);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('bidu', 'Bidu', 'cachorro', 'Oi, eu sou o Bidu. Fui atacado por outro cachorro e precisei de uma cirurgia na mandíbula. Me recuperei, mas agora estou tratando um tumor (TVT). Sigo firme!', 'um ursinho de pelúcia bem fofinho para me fazer companhia', 'Oi, eu sou o Bidu. Fui atacado por outro cachorro e precisei de uma cirurgia na mandíbula. Me recuperei, mas agora estou tratando um tumor (TVT). Sigo firme! Papai Noel, neste Natal eu queria muito ganhar um ursinho de pelúcia bem fofinho para me fazer companhia.', '/pets/bidu.png', 'brinquedo', '[]', 1, 'disponivel', 12);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('bob', 'Bob', 'cachorro', 'Oi, eu sou o Bob. Nasci em um buraco em 2021 e fui adotado ainda filhote, mas meu dono se mudou e me deixou para trás. Assim, voltei para o abrigo.', 'uma mantinha quentinha e macia para os dias frios', 'Oi, eu sou o Bob. Nasci em um buraco em 2021 e fui adotado ainda filhote, mas meu dono se mudou e me deixou para trás. Assim, voltei para o abrigo. Papai Noel, neste Natal eu queria muito ganhar uma mantinha quentinha e macia para os dias frios.', '/pets/bob.png', 'conforto', '[]', 1, 'disponivel', 13);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('branca', 'Branca', 'cachorro', 'Oi, eu sou a Branca, uma pitbull idosinha. Estou no abrigo há quase 9 anos. Fui explorada pelos meus antigos donos e, até hoje, sou medrosa e demoro a confiar.', 'uma caminha grande e aconchegante para aproveitar minha velhice em paz', 'Oi, eu sou a Branca, uma pitbull idosinha. Estou no abrigo há quase 9 anos. Fui explorada pelos meus antigos donos e, até hoje, sou medrosa e demoro a confiar. Papai Noel, neste Natal eu queria muito ganhar uma caminha grande e aconchegante para aproveitar minha velhice em paz.', '/pets/branca.png', 'cama', '[]', 1, 'disponivel', 14);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('bruce', 'Bruce', 'indefinido', 'Oi, eu sou o Bruce. Cheguei ao abrigo filhote, em 2020, e há 6 anos espero por uma família. Mesmo assim, nunca perdi minha alegria.', 'um kit de petiscos variados para dividir com meus amiguinhos', 'Oi, eu sou o Bruce. Cheguei ao abrigo filhote, em 2020, e há 6 anos espero por uma família. Mesmo assim, nunca perdi minha alegria. Papai Noel, neste Natal eu queria muito ganhar um kit de petiscos variados para dividir com meus amiguinhos.', '/pets/bruce.png', 'petisco', '[]', 1, 'disponivel', 15);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('cafe', 'Café', 'gato', 'Oi, eu sou o Café. Tenho uns 5 anos e quase morri nas ruas depois de ser envenenado com chumbinho. Fui socorrido a tempo e ganhei uma segunda chance.', 'um kit de tapetes EVA coloridos para o nosso gatil', 'Oi, eu sou o Café. Tenho uns 5 anos e quase morri nas ruas depois de ser envenenado com chumbinho. Fui socorrido a tempo e ganhei uma segunda chance. Papai Noel, neste Natal eu queria muito ganhar um kit de tapetes EVA coloridos para o nosso gatil.', '/pets/cafe.png', 'petisco', '[]', 1, 'disponivel', 16);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('cafu', 'Cafu', 'indefinido', 'Oi, eu sou o Cafu. Tenho apenas 4 meses e sou um bebezão cheio de energia e curiosidade.', 'brinquedos para gastar minha energia enquanto espero pela minha família', 'Oi, eu sou o Cafu. Tenho apenas 4 meses e sou um bebezão cheio de energia e curiosidade. Papai Noel, neste Natal eu queria muito ganhar brinquedos para gastar minha energia enquanto espero pela minha família.', '/pets/cafu.png', 'brinquedo', '[]', 1, 'disponivel', 17);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('caramelo', 'Caramelo', 'indefinido', 'Oi, eu sou o Caramelo. Tenho 4 anos e fui resgatado depois de um atropelamento. Hoje estou seguro e recebendo muito carinho.', 'mantinhas quentinhas e macias para os dias frios', 'Oi, eu sou o Caramelo. Tenho 4 anos e fui resgatado depois de um atropelamento. Hoje estou seguro e recebendo muito carinho. Papai Noel, neste Natal eu queria muito ganhar mantinhas quentinhas e macias para os dias frios.', '/pets/caramelo.png', 'conforto', '[]', 1, 'disponivel', 18);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('carcoso', 'Carcoso', 'cachorro', 'Oi, eu sou o Carcoso. Cheguei filhote, em 2022. Tive cinomose e parvovirose, mas sobrevivi sem sequelas.', 'um bichinho de pelúcia', 'Oi, eu sou o Carcoso. Cheguei filhote, em 2022. Tive cinomose e parvovirose, mas sobrevivi sem sequelas. Papai Noel, neste Natal eu queria muito ganhar um bichinho de pelúcia.', '/pets/carcoso.png', 'brinquedo', '[]', 1, 'disponivel', 19);
