INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('cristal', 'Cristal', 'indefinido', 'Oi, eu sou a Cristal. Estou no abrigo desde 2019. Fui atropelada enquanto cuidava dos meus filhotes e, com muito tratamento, voltei a andar. Fiquei com sequelas e tomo medicação controlada.', 'uma caminha grande, macia e confortável', 'Oi, eu sou a Cristal. Estou no abrigo desde 2019. Fui atropelada enquanto cuidava dos meus filhotes e, com muito tratamento, voltei a andar. Fiquei com sequelas e tomo medicação controlada. Papai Noel, neste Natal eu queria muito ganhar uma caminha grande, macia e confortável.', '/pets/cristal.png', 'cama', '[]', 1, 'disponivel', 21);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('dandara', 'Dandara', 'cachorro', 'Oi, eu sou a Dandara. Cheguei ao abrigo em 2019 com uma patinha cheia de feridas e larvas. Me recuperei e hoje sou uma das senhorinhas da turma.', 'um tapete de farejar e alguns petiscos gostosos', 'Oi, eu sou a Dandara. Cheguei ao abrigo em 2019 com uma patinha cheia de feridas e larvas. Me recuperei e hoje sou uma das senhorinhas da turma. Papai Noel, neste Natal eu queria muito ganhar um tapete de farejar e alguns petiscos gostosos.', '/pets/dandara.png', 'petisco', '[]', 1, 'disponivel', 22);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('darlene', 'Darlene', 'indefinido', 'Oi, eu sou a Darlene. Fui resgatada das ruas e ainda tenho muito medo. Às vezes tomo chuva porque não me sinto segura nas partes cobertas.', 'uma casinha para ficar protegida', 'Oi, eu sou a Darlene. Fui resgatada das ruas e ainda tenho muito medo. Às vezes tomo chuva porque não me sinto segura nas partes cobertas. Papai Noel, neste Natal eu queria muito ganhar uma casinha para ficar protegida.', '/pets/darlene.png', 'cama', '[]', 1, 'disponivel', 23);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('dominic', 'Dominic', 'indefinido', 'Oi, eu sou o Dominic. Vivia nas ruas, me escondendo do sol embaixo de um móvel velho. Fui o primeiro morador da chácara do projeto.', 'uma caminha bem quentinha', 'Oi, eu sou o Dominic. Vivia nas ruas, me escondendo do sol embaixo de um móvel velho. Fui o primeiro morador da chácara do projeto. Papai Noel, neste Natal eu queria muito ganhar uma caminha bem quentinha.', '/pets/dominic.png', 'cama', '[]', 1, 'disponivel', 24);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('donzelo', 'Donzelo', 'indefinido', 'Oi, eu sou o Donzelo. Nasci em uma praça movimentada e estou aqui há 2 anos. Sou muito brincalhão.', 'um brinquedo', 'Oi, eu sou o Donzelo. Nasci em uma praça movimentada e estou aqui há 2 anos. Sou muito brincalhão. Papai Noel, neste Natal eu queria muito ganhar um brinquedo.', '/pets/donzelo.png', 'brinquedo', '[]', 1, 'disponivel', 25);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('duque', 'Duque', 'cachorro', 'Oi, eu sou o Duque. Fui abandonado perto do aeroporto e estou no abrigo há mais de 1 ano. Tratei um tumor (TVT) e hoje estou 100% recuperado!', 'uma piscininha infantil para me refrescar nos dias quentes', 'Oi, eu sou o Duque. Fui abandonado perto do aeroporto e estou no abrigo há mais de 1 ano. Tratei um tumor (TVT) e hoje estou 100% recuperado! Papai Noel, neste Natal eu queria muito ganhar uma piscininha infantil para me refrescar nos dias quentes.', '/pets/duque.png', 'outros', '[]', 1, 'disponivel', 26);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('eric', 'Eric', 'cachorro', 'Oi, eu sou o Eric. Nasci em um terminal de ônibus. Fui adotado, mas vivia amarrado, então a tia do abrigo foi me buscar. Sou brincalhão e feliz.', 'uma orelha defumada ou um osso', 'Oi, eu sou o Eric. Nasci em um terminal de ônibus. Fui adotado, mas vivia amarrado, então a tia do abrigo foi me buscar. Sou brincalhão e feliz. Papai Noel, neste Natal eu queria muito ganhar uma orelha defumada ou um osso.', '/pets/eric.png', 'petisco', '[]', 1, 'disponivel', 27);
