INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('fatima', 'Fátima', 'indefinido', 'Oi, eu sou a Fátima. Cheguei grávida de 7 bebês. Meu filho que ficou aqui entra em pânico sem mim, e ninguém quis nos adotar juntos.', 'uma caminha bem quentinha para dormirmos juntos', 'Oi, eu sou a Fátima. Cheguei grávida de 7 bebês. Meu filho que ficou aqui entra em pânico sem mim, e ninguém quis nos adotar juntos. Papai Noel, neste Natal nós queríamos muito ganhar uma caminha bem quentinha para dormirmos juntos.', '/pets/fatima.png', 'cama', '[]', 1, 'disponivel', 29);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('fiona', 'Fiona', 'indefinido', 'Oi, eu sou a Fiona. Estou no abrigo desde filhote, em 2021. Já vi muitos amiguinhos serem adotados, mas a minha vez ainda não chegou.', 'uma mantinha quentinha e macia para os dias frios', 'Oi, eu sou a Fiona. Estou no abrigo desde filhote, em 2021. Já vi muitos amiguinhos serem adotados, mas a minha vez ainda não chegou. Papai Noel, neste Natal eu queria muito ganhar uma mantinha quentinha e macia para os dias frios.', '/pets/fiona.png', 'conforto', '[]', 1, 'disponivel', 30);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('fred', 'Fred', 'indefinido', 'Oi, eu sou o Fred. Cheguei ao abrigo filhote e hoje tenho uns 5 anos. Até agora, ninguém me escolheu.', 'uma casinha pequena e aconchegante para me esconder e tirar sonecas', 'Oi, eu sou o Fred. Cheguei ao abrigo filhote e hoje tenho uns 5 anos. Até agora, ninguém me escolheu. Papai Noel, neste Natal eu queria muito ganhar uma casinha pequena e aconchegante para me esconder e tirar sonecas.', '/pets/fred.png', 'cama', '[]', 1, 'disponivel', 31);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('garfield', 'Garfield', 'gato', 'Oi, eu sou o Garfield. Tenho uns 6 anos e fui resgatado de um lugar onde envenenavam gatos. Hoje estou protegido, mas sonho com um lar sem medo.', 'um arranhador resistente para afiar as unhas e me divertir', 'Oi, eu sou o Garfield. Tenho uns 6 anos e fui resgatado de um lugar onde envenenavam gatos. Hoje estou protegido, mas sonho com um lar sem medo. Papai Noel, neste Natal eu queria muito ganhar um arranhador resistente para afiar as unhas e me divertir.', '/pets/garfield.png', 'conforto', '[]', 1, 'disponivel', 32);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('glorinha', 'Glorinha', 'cachorro', 'Oi, eu sou a Glorinha. Cheguei ao abrigo em 2022 com cinomose. Venci a doença e, mesmo com algumas sequelas, hoje vivo bem.', 'uma caminha grande, macia e confortável para minhas sonecas', 'Oi, eu sou a Glorinha. Cheguei ao abrigo em 2022 com cinomose. Venci a doença e, mesmo com algumas sequelas, hoje vivo bem. Papai Noel, neste Natal eu queria muito ganhar uma caminha grande, macia e confortável para minhas sonecas.', '/pets/glorinha.png', 'cama', '[]', 1, 'disponivel', 33);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('gohan', 'Gohan', 'cachorro', 'Oi, eu sou o Gohan. Vivia perto de um condomínio, até que começaram a implicar comigo, mesmo eu não sendo uma ameaça.', 'um ossinho ou uma orelha defumada', 'Oi, eu sou o Gohan. Vivia perto de um condomínio, até que começaram a implicar comigo, mesmo eu não sendo uma ameaça. Papai Noel, neste Natal eu queria muito ganhar um ossinho ou uma orelha defumada.', '/pets/gohan.png', 'petisco', '[]', 1, 'disponivel', 34);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('goji-berry', 'Goji Berry', 'indefinido', 'Oi, eu sou o Goji Berry. Nasci no mato e fui resgatado com minha mãe e meus irmãos. Tenho 1 ano e meio e sou muito brincalhão.', 'uma piscina de bolinhas infantil', 'Oi, eu sou o Goji Berry. Nasci no mato e fui resgatado com minha mãe e meus irmãos. Tenho 1 ano e meio e sou muito brincalhão. Papai Noel, neste Natal eu queria muito ganhar uma piscina de bolinhas infantil.', '/pets/goji-berry.png', 'brinquedo', '[]', 1, 'disponivel', 35);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('gueto', 'Gueto', 'cachorro', 'Oi, eu sou o Gueto. Ainda bebê, fui abandonado em uma fábrica com vários outros cães. Já estou há 2 anos aqui.', 'um brinquedo', 'Oi, eu sou o Gueto. Ainda bebê, fui abandonado em uma fábrica com vários outros cães. Já estou há 2 anos aqui. Papai Noel, neste Natal eu queria muito ganhar um brinquedo.', '/pets/gueto.png', 'brinquedo', '[]', 1, 'disponivel', 36);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('hanna', 'Hanna', 'cachorro', 'Oi, eu sou a Hanna. Tive 12 bebês em um túmulo de cemitério, depois de muitas outras ninhadas. Hoje estou livre desse sofrimento.', 'uma caminha suspensa, porque na seca tudo fica sujo de terra', 'Oi, eu sou a Hanna. Tive 12 bebês em um túmulo de cemitério, depois de muitas outras ninhadas. Hoje estou livre desse sofrimento. Papai Noel, neste Natal eu queria muito ganhar uma caminha suspensa, porque na seca tudo fica sujo de terra.', '/pets/hanna.png', 'cama', '[]', 1, 'disponivel', 37);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('hulk', 'Hulk', 'indefinido', 'Oi, eu sou o Hulk. Estou no abrigo desde filhote, em 2021, e nunca perdi minha alegria e vontade de brincar.', 'uma piscina de bolinhas coloridas para brincar com meus amigos', 'Oi, eu sou o Hulk. Estou no abrigo desde filhote, em 2021, e nunca perdi minha alegria e vontade de brincar. Papai Noel, neste Natal eu queria muito ganhar uma piscina de bolinhas coloridas para brincar com meus amigos.', '/pets/hulk.png', 'brinquedo', '[]', 1, 'disponivel', 38);
