INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('jade', 'Jade', 'indefinido', 'Oi, eu sou a Jade. Tenho 5 meses e fui resgatada com minha mãe e meus irmãos. Minha mãe não resistiu e meus irmãos já foram adotados, mas eu continuo aqui.', 'um brinquedo interativo com bolinhas e petiscos para gastar minha energia de filhotona', 'Oi, eu sou a Jade. Tenho 5 meses e fui resgatada com minha mãe e meus irmãos. Minha mãe não resistiu e meus irmãos já foram adotados, mas eu continuo aqui. Papai Noel, neste Natal eu queria muito ganhar um brinquedo interativo com bolinhas e petiscos para gastar minha energia de filhotona.', '/pets/jade.png', 'brinquedo', '[]', 1, 'disponivel', 40);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('joca', 'Joca', 'indefinido', 'Oi, eu sou o Joca. Estou no abrigo desde 2019. Já sou um senhorzinho, mas continuo alegre e cheio de energia, esperando um lar para minha velhice.', 'uma caminha confortável e petiscos bem gostosos', 'Oi, eu sou o Joca. Estou no abrigo desde 2019. Já sou um senhorzinho, mas continuo alegre e cheio de energia, esperando um lar para minha velhice. Papai Noel, neste Natal eu queria muito ganhar uma caminha confortável e petiscos bem gostosos.', '/pets/joca.png', 'petisco', '[]', 1, 'disponivel', 41);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('jorge', 'Jorge', 'cachorro', 'Oi, eu sou o Jorge. Nasci em um buraco em 2021 e precisei da ajuda dos bombeiros para ser resgatado. Meus irmãos foram adotados e só ficamos eu e meu maninho Bob.', 'uma mantinha quentinha e macia para os dias frios', 'Oi, eu sou o Jorge. Nasci em um buraco em 2021 e precisei da ajuda dos bombeiros para ser resgatado. Meus irmãos foram adotados e só ficamos eu e meu maninho Bob. Papai Noel, neste Natal eu queria muito ganhar uma mantinha quentinha e macia para os dias frios.', '/pets/jorge.png', 'conforto', '[]', 1, 'disponivel', 42);
