INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('sadia', 'Sadia', 'cachorro', 'Oi, eu sou a Sadia. Fui abandonada quando meus donos se mudaram, e meus 2 filhotinhos não resistiram. Estou aqui há quase 1 ano e ainda sou medrosa.', 'um osso defumado, minha coisa favorita', 'Oi, eu sou a Sadia. Fui abandonada quando meus donos se mudaram, e meus 2 filhotinhos não resistiram. Estou aqui há quase 1 ano e ainda sou medrosa. Papai Noel, neste Natal eu queria muito ganhar um osso defumado, minha coisa favorita.', '/pets/sadia.png', 'petisco', '[]', 1, 'disponivel', 68);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('scooby', 'Scooby', 'indefinido', 'Oi, eu sou o Scooby. Estou no abrigo há 2 anos, desde que fui atropelado e não conseguia andar. Recebi cuidados e ganhei uma nova chance.', 'um kit de petiscos variados', 'Oi, eu sou o Scooby. Estou no abrigo há 2 anos, desde que fui atropelado e não conseguia andar. Recebi cuidados e ganhei uma nova chance. Papai Noel, neste Natal eu queria muito ganhar um kit de petiscos variados.', '/pets/scooby.png', 'petisco', '[]', 1, 'disponivel', 69);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('sidney', 'Sidney', 'indefinido', 'Oi, eu sou o Sidney. Ainda sou tímido, mas estou me soltando aos poucos.', 'patês ou petiscos', 'Oi, eu sou o Sidney. Ainda sou tímido, mas estou me soltando aos poucos. Papai Noel, neste Natal eu queria muito ganhar patês ou petiscos.', '/pets/sidney.png', 'petisco', '[]', 1, 'disponivel', 70);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('sortudo', 'Sortudo', 'gato', 'Oi, eu sou o Sortudo. Tenho uns 6 anos e fui encontrado nas ruas com uma sarna muito forte. Fui tratado e hoje estou saudável.', 'um arranhador para alegrar ainda mais os meus dias', 'Oi, eu sou o Sortudo. Tenho uns 6 anos e fui encontrado nas ruas com uma sarna muito forte. Fui tratado e hoje estou saudável. Papai Noel, neste Natal eu queria muito ganhar um arranhador para alegrar ainda mais os meus dias.', '/pets/sortudo.png', 'conforto', '[]', 1, 'disponivel', 71);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('tadeu', 'Tadeu', 'indefinido', 'Oi, eu sou o Tadeu. Fui atropelado e cheguei com uma ferida feia na cabeça. Me recuperei e hoje sou um menino cheio de energia.', 'um brinquedo recheável com petiscos para gastar energia', 'Oi, eu sou o Tadeu. Fui atropelado e cheguei com uma ferida feia na cabeça. Me recuperei e hoje sou um menino cheio de energia. Papai Noel, neste Natal eu queria muito ganhar um brinquedo recheável com petiscos para gastar energia.', '/pets/tadeu.png', 'brinquedo', '[]', 1, 'disponivel', 72);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('ted', 'Ted', 'cachorro', 'Oi, eu sou o Ted, um Akita de 12 anos. Voltei para casa sem conseguir andar e meu tutor quis me sacrificar, mas o abrigo me deu uma nova chance. Hoje faço fisioterapia e estou voltando a andar.', 'um kit de tapetes de EVA para não escorregar durante a recuperação', 'Oi, eu sou o Ted, um Akita de 12 anos. Voltei para casa sem conseguir andar e meu tutor quis me sacrificar, mas o abrigo me deu uma nova chance. Hoje faço fisioterapia e estou voltando a andar. Papai Noel, neste Natal eu queria muito ganhar um kit de tapetes de EVA para não escorregar durante a recuperação.', '/pets/ted.png', 'petisco', '[]', 1, 'disponivel', 73);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('tigrona', 'Tigrona', 'cachorro', 'Oi, eu sou a Tigrona. Cheguei ao abrigo em 2020 com meus filhotes recém-nascidos. Sou grandona, brincalhona e carinhosa.', 'um mordedor grande, para cães do meu tamanho', 'Oi, eu sou a Tigrona. Cheguei ao abrigo em 2020 com meus filhotes recém-nascidos. Sou grandona, brincalhona e carinhosa. Papai Noel, neste Natal eu queria muito ganhar um mordedor grande, para cães do meu tamanho.', '/pets/tigrona.png', 'brinquedo', '[]', 1, 'disponivel', 74);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('tita', 'Tita', 'indefinido', 'Oi, eu sou a Tita. Cheguei há pouco tempo. Gosto do meu cantinho, mas ainda tenho medo de tudo.', 'uma caminha bem quentinha', 'Oi, eu sou a Tita. Cheguei há pouco tempo. Gosto do meu cantinho, mas ainda tenho medo de tudo. Papai Noel, neste Natal eu queria muito ganhar uma caminha bem quentinha.', '/pets/tita.png', 'cama', '[]', 1, 'disponivel', 75);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('toquinho', 'Toquinho', 'cachorro', 'Oi, eu sou o Toquinho. Cheguei ao abrigo filhote, em 2020, com meus irmãos. Já são 6 anos esperando a minha vez.', 'um mordedor de corda grande para brincar de cabo de guerra e perder uns quilinhos', 'Oi, eu sou o Toquinho. Cheguei ao abrigo filhote, em 2020, com meus irmãos. Já são 6 anos esperando a minha vez. Papai Noel, neste Natal eu queria muito ganhar um mordedor de corda grande para brincar de cabo de guerra e perder uns quilinhos.', '/pets/toquinho.png', 'brinquedo', '[]', 1, 'disponivel', 76);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('valdo', 'Valdo', 'indefinido', 'Oi, eu sou o Valdo. Nasci aqui em 2023. Minhas irmãs foram adotadas, mas eu nunca fui escolhido.', 'um brinquedinho', 'Oi, eu sou o Valdo. Nasci aqui em 2023. Minhas irmãs foram adotadas, mas eu nunca fui escolhido. Papai Noel, neste Natal eu queria muito ganhar um brinquedinho.', '/pets/valdo.png', 'outros', '[]', 1, 'disponivel', 77);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('vegas', 'Vegas', 'cachorro', 'Oi, eu sou o Vegas. Fui encontrado pedindo comida em um restaurante. Há 3 anos procuro um lar, mas é difícil um cão como eu ter uma chance.', 'um brinquedo', 'Oi, eu sou o Vegas. Fui encontrado pedindo comida em um restaurante. Há 3 anos procuro um lar, mas é difícil um cão como eu ter uma chance. Papai Noel, neste Natal eu queria muito ganhar um brinquedo.', '/pets/vegas.png', 'brinquedo', '[]', 1, 'disponivel', 78);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('vitoria', 'Vitória', 'indefinido', 'Oi, eu sou a Vitória. Fui encontrada em uma região rural, muito magrinha, e recebi os cuidados de que precisava.', 'uma casinha tamanho médio para ter um cantinho só meu', 'Oi, eu sou a Vitória. Fui encontrada em uma região rural, muito magrinha, e recebi os cuidados de que precisava. Papai Noel, neste Natal eu queria muito ganhar uma casinha tamanho médio para ter um cantinho só meu.', '/pets/vitoria.png', 'cama', '[]', 1, 'disponivel', 79);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('vladimir', 'Vladimir', 'indefinido', 'Oi, eu sou o Vladimir. Cheguei há 2 anos, com 3 meses, depois que meus irmãos morreram em uma casa onde nem as pessoas tinham o que comer.', 'um brinquedo bem legal', 'Oi, eu sou o Vladimir. Cheguei há 2 anos, com 3 meses, depois que meus irmãos morreram em uma casa onde nem as pessoas tinham o que comer. Papai Noel, neste Natal eu queria muito ganhar um brinquedo bem legal.', '/pets/vladimir.png', 'brinquedo', '[]', 1, 'disponivel', 80);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('vrinzim', 'Vrinzim', 'indefinido', 'Oi, eu sou o Vrinzim. Fui resgatado no mato com 2 dias de vida. Sou arredio e medroso, o que dificulta minha adoção, mas aqui sou alegre e brincalhão.', 'petiscos', 'Oi, eu sou o Vrinzim. Fui resgatado no mato com 2 dias de vida. Sou arredio e medroso, o que dificulta minha adoção, mas aqui sou alegre e brincalhão. Papai Noel, neste Natal eu queria muito ganhar petiscos.', '/pets/vrinzim.png', 'petisco', '[]', 1, 'disponivel', 81);
INSERT OR IGNORE INTO animais (id, nome, especie, historia, pedido, cartinha, foto, categoria, links_compra, ativo, status, ordem) VALUES ('zuko', 'Zuko', 'cachorro', 'Oi, eu sou o Zuko, mestiço de pitbull. Fui resgatado muito machucado depois de uma briga com outro animal. Hoje sou forte, cheio de energia e um pouquinho ansioso.', 'um brinquedo recheável que libera petiscos aos poucos', 'Oi, eu sou o Zuko, mestiço de pitbull. Fui resgatado muito machucado depois de uma briga com outro animal. Hoje sou forte, cheio de energia e um pouquinho ansioso. Papai Noel, neste Natal eu queria muito ganhar um brinquedo recheável que libera petiscos aos poucos.', '/pets/zuko.png', 'brinquedo', '[]', 1, 'disponivel', 82);

