-- ===== MIGRAÇÃO: adocoes antigas -> padrinhos + reservas =====
-- 1) cria um padrinho por adoção (id determinístico = 100000 + adocoes.id)
INSERT OR IGNORE INTO padrinhos (id, nome, whatsapp, email, criado_em)
SELECT 100000 + a.id, a.padrinho_nome, a.padrinho_contato, NULL, a.criado_em
FROM adocoes a
WHERE EXISTS (SELECT 1 FROM animais an WHERE an.id = a.pet_id)
  AND NOT EXISTS (SELECT 1 FROM reservas r WHERE r.animal_id = a.pet_id AND r.status <> 'cancelada');

-- 2) cria a reserva ligada ao padrinho acima (status 'reservada')
INSERT OR IGNORE INTO reservas (codigo, animal_id, padrinho_id, modalidade, status, criado_em, atualizado_em)
SELECT printf('NP-MIG-%06d', a.id), a.pet_id, 100000 + a.id, NULL, 'reservada', a.criado_em, a.criado_em
FROM adocoes a
WHERE EXISTS (SELECT 1 FROM animais an WHERE an.id = a.pet_id)
  AND NOT EXISTS (SELECT 1 FROM reservas r WHERE r.animal_id = a.pet_id AND r.status <> 'cancelada');

-- 3) marca como 'reservada' todo animal que tenha reserva ativa
UPDATE animais SET status = 'reservada', atualizado_em = datetime('now')
WHERE status = 'disponivel'
  AND id IN (SELECT animal_id FROM reservas WHERE status <> 'cancelada');
